import React, { useState, useEffect, useRef } from 'react';
import Plot from 'react-plotly.js';
import { getTopicIdByLabel, getTopicLabel } from './topic-labels.js';
const PERSONA_PERIOD_OPTIONS = [1, 2, 3, 4, 5];




const topicColorMap = {
  "2": 'rgb(229, 134, 6)', "3": 'rgb(93, 105, 177)', "1": 'rgb(82, 188, 163)',
  "0": 'rgb(153, 201, 69)', "9": 'rgb(204, 97, 176)', "6": 'rgb(36, 121, 108)',
  "8": 'rgb(218, 165, 27)', "7": 'rgb(47, 138, 196)', "11": 'rgb(118, 78, 159)',
};
const fallbackColor = 'rgb(170, 170, 170)';


// fetchData関数：JSONまたはテキスト形式に対応
const fetchData = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
      return await response.json(); // JSON形式の場合
    } else {
      const text = await response.text(); // プレーンテキストの場合
      return text.split("\n").filter(line => line.trim() !== ""); // 改行区切りのデータを配列として返す
    }
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return [];
  }
};

// スパースデータから特定行（会社）の合計値だけを直接集計
const sumSparseRow = (sparseData, targetRow) => {
  if (!Array.isArray(sparseData) || targetRow < 0) {
    return 0;
  }
  return sparseData.reduce((sum, entry) => {
    if (!entry || Number(entry.row) !== targetRow) {
      return sum;
    }
    const value = Number(entry.value);
    return Number.isFinite(value) ? sum + value : sum;
  }, 0);
};

const PlotPieB = ({ update, visualType, topic, company, onRendered, onClickData, topicLabelMap }) => {
  const [chartData, setChartData] = useState([]);
  const [title, setTitle] = useState("注目トピックに関する特許の企業占有率");
  const [selectedTime, setSelectedTime] = useState(5);
  const selectedCompany = Array.isArray(company) ? String(company[0] ?? '') : String(company ?? '');
  const allTopic = (Array.isArray(topic) && topic.length > 0 ? topic : ['2', '3', '1', '0', '9', '6', '8', '7', '11'])
    .map((id) => Number(id));
  // キャッシュ用のオブジェクト
  const dataCache = useRef({
    companies: {},
    sparseData: {}
  });

  const loadData = async () => {
    try {
      const allTopicsData = await Promise.all(
        allTopic.map(async (target_id) => {
          const sparseDataUrl = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/occupy/occupy_topic_${selectedTime}.json`;
          const sparseCacheKey = `${target_id}-${selectedTime}`;
          const companyUrl = `${process.env.PUBLIC_URL}/data/visualize_data/topic${target_id}/span=3/setting/company.txt`;

          if (!dataCache.current.sparseData[sparseCacheKey]) {
            dataCache.current.sparseData[sparseCacheKey] = await fetchData(sparseDataUrl);
          }

          const sparsePayload = dataCache.current.sparseData[sparseCacheKey];
          const sparseData = Array.isArray(sparsePayload?.data)
            ? sparsePayload.data
            : (Array.isArray(sparsePayload) ? sparsePayload : []);

          // 新形式は occupy_topic 内に companies が含まれる。旧形式では company.txt を利用。
          if (!dataCache.current.companies[target_id]) {
            if (Array.isArray(sparsePayload?.companies) && sparsePayload.companies.length > 0) {
              dataCache.current.companies[target_id] = sparsePayload.companies;
            } else {
              dataCache.current.companies[target_id] = await fetchData(companyUrl);
            }
          }
          const companies = dataCache.current.companies[target_id];

          // 正規化関数
          const normalizeString = (str) => {
            if (typeof str !== "string") {
              console.warn("非文字列データが検出されました:", str);
              return null; // 非文字列データは無視
            }
            return str.normalize("NFC").trim(); // 正規化とトリムを適用
          };

          // 正規化したデータで比較
          const sanitizedCompanies = companies.map(normalizeString);
          const sanitizedCompany = normalizeString(selectedCompany);

          if (!sanitizedCompanies.includes(sanitizedCompany)) {
            console.warn(`Company "${sanitizedCompany}" not found in topic ${target_id}`);
            return null;
          }

          const companyIndex = sanitizedCompanies.indexOf(sanitizedCompany);
          const companyValue = sumSparseRow(sparseData, companyIndex);
          return { topic: target_id, value: companyValue };
        })
      );

      const filteredData = allTopicsData.filter((data) => data !== null);

      // 正規化とソート
      const totalValue = filteredData.reduce((sum, item) => sum + item.value, 0);
      if (totalValue === 0) {
        console.warn("No valid data to normalize.");
        setChartData([]);
        return;
      }



      const normalizedData = filteredData.map(item => ({
        category: item.topic,
        value: item.value / totalValue,
      })).sort((a, b) => b.value - a.value);

      const top10 = normalizedData.slice(0, 10);
      const othersValue = normalizedData.slice(10).reduce((sum, item) => sum + item.value, 0);
      const withOthers = othersValue > 0
        ? [...top10, { category: 'others', value: othersValue }]
        : top10;

      setChartData(withOthers);
      const companyName = selectedCompany || '注目企業';
      setTitle(`${companyName}の注目トピック占有率（時間 ${selectedTime}）`);
      onRendered(); // 描画完了を通知
    } catch (error) {
      console.error("データ処理中のエラー:", error);
    }
  };

  // 初期データ読み込みとupdateの変更時にデータをロード
  useEffect(() => {
    if (visualType === "one-comp") {
      loadData();
    }
  }, [update, visualType, JSON.stringify(topic), selectedCompany, selectedTime]);

  const handlePlotClick = (event) => {
    if (event.points && event.points[0]) {
      const clickdata = event.points[0].label; // クリックされた部分のラベル
      if (clickdata === 'その他') {
        return;
      }
      const topicid = getTopicIdByLabel(clickdata, topicLabelMap);
      if (topicid) {
        onClickData([topicid]); // 親コンポーネントにラベルを通知
      }
    }
  };

  return (
    <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '6px' }}>
        {PERSONA_PERIOD_OPTIONS.map((time) => (
          <button
            key={time}
            type="button"
            className={`btn btn-sm ${selectedTime === time ? 'btn-primary' : 'btn-outline-primary'}`}
            onClick={() => setSelectedTime(time)}
          >
            {time}期
          </button>
        ))}
      </div>
      <Plot
        data={[
          {
            type: "pie",
            values: chartData.map(item => item.value),
            labels: chartData.map((item) =>
              item.category === 'others' ? 'その他' : getTopicLabel(String(item.category), topicLabelMap)
            ),
            direction: "clockwise",
            sort: false,
            marker: {
              colors: chartData.map((item) =>
                item.category === 'others'
                  ? 'rgb(200, 200, 200)'
                  : (topicColorMap[String(item.category)] || fallbackColor)
              ),
            },
          },
        ]}
        layout={{
          title: title,
          showlegend: true,
          plot_bgcolor: "white",
          paper_bgcolor: "white",
          margin: { t: 70, b: 5, l: 40, r: 50 },
        }}
        style={{ width: '100%', height: '100%', minHeight: 0 }} // 必ず全体サイズを親要素に合わせ
        onClick={handlePlotClick} // クリックイベントを追加
      />
     
    </div>
  );
};

export default PlotPieB;
