import React, { useState, useEffect } from "react";
import Plot from "react-plotly.js";
import { getTopicLabel } from './topic-labels.js';
const PERSONA_PERIOD_OPTIONS = [1, 2, 3, 4, 5];

// データをロードする関数
const fetchData = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    return await response.json();
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return [];
  }
};

// テキストデータを読み込む関数
const fetchTextData = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const text = await response.text();
    return text.split("\n").filter((line) => line.trim() !== "");
  } catch (error) {
    console.error("データの読み込みエラー:", error);
    return [];
  }
};

const PlotPieA = ({ update, visualType, topic, onRendered, topicLabelMap }) => {
  const [chartData, setChartData] = useState([]);
  const [title, setTitle] = useState("");
  const [selectedTime, setSelectedTime] = useState(5);
  const activeTopicId = Array.isArray(topic) ? String(topic[0] ?? '') : String(topic ?? '');
  const truncateLabel = (label) => {
    const text = String(label || '');
    return text.length > 10 ? `${text.slice(0, 10)}…` : text;
  };

  const colormap = {'鹿島建設株式会社':'rgb(229, 134, 6)', "株式会社大林組":'rgb(93, 105, 177)', "清水建設株式会社":'rgb(82, 188, 163)',
      "大成建設株式会社":'rgb(153, 201, 69)', "株式会社竹中工務店":'rgb(204, 97, 176)', "株式会社長谷工コーポレーション":'rgb(36, 121, 108)', 
      "前田建設工業株式会社":'rgb(218, 165, 27)',"五洋建設株式会社":'rgb(47, 138, 196)', "株式会社フジタ":'rgb(118, 78, 159)', 
      "戸田建設株式会社":'rgb(237, 100, 90)', "株式会社熊谷組":'rgb(165, 170, 153)'};
     

  useEffect(() => {
    const loadChartData = async () => {
      try {
        const targetId = activeTopicId;
        if (!targetId) {
          setChartData([]);
          setTitle('TOPICを選択してください');
          return;
        }
        const dataUrl = `${process.env.PUBLIC_URL}/data/visualize_data/topic${targetId}/span=3/occupy/occupy_mean_${selectedTime}.json`;
        const columnUrl = `${process.env.PUBLIC_URL}/data/visualize_data/topic${targetId}/span=3/setting/company.txt`;

        // データ取得
        const [values, labels] = await Promise.all([
          fetchData(dataUrl),
          fetchTextData(columnUrl),
        ]);

        // 値とラベルの組み合わせを作成
        // occupy_mean は { value: [] } 形式と [{company,value}] 形式の両方を許容
        let valueByCompany = {};
        if (Array.isArray(values)) {
          valueByCompany = values.reduce((acc, item) => {
            if (item && typeof item.company === 'string') {
              acc[item.company] = Number(item.value) || 0;
            }
            return acc;
          }, {});
        }

        const data = labels.length > 0
          ? labels.map((label, index) => {
              const fallbackFromLegacy =
                values && values.value && Array.isArray(values.value) ? Number(values.value[index]) || 0 : 0;
              const normalizedValue = Object.prototype.hasOwnProperty.call(valueByCompany, label)
                ? valueByCompany[label]
                : fallbackFromLegacy;
              return {
                label,
                value: normalizedValue,
              };
            })
          : (Array.isArray(values)
              ? values
                  .filter((item) => item && typeof item.company === 'string')
                  .map((item) => ({
                    label: item.company,
                    value: Number(item.value) || 0,
                  }))
              : []);

        // 値に基づいて降順にソートして上位10件を抽出
        const sortedData = data
          .sort((a, b) => b.value - a.value)
          .slice(0, 10);

        const remainingData = data.slice(10);
        const othersValue = remainingData.reduce((sum, item) => sum + (Number(item.value) || 0), 0);
        const withOthers = othersValue > 0
          ? [...sortedData, { label: 'その他', value: othersValue }]
          : sortedData;

        setChartData(withOthers);
        setTitle(`${getTopicLabel(targetId, topicLabelMap)}に関する特許の企業占有率（時間 ${selectedTime}）`);
        if (onRendered) onRendered(); // 描画完了を通知
      } catch (error) {
        console.error("チャートデータの処理中にエラー:", error);
      }
    };

    // 初回レンダリング時と`update`変更時にデータをロード
    if (visualType === "one-topic") {
      loadChartData();
    }
  }, [update, visualType, activeTopicId, onRendered, topicLabelMap, selectedTime]);

  return (
    <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <div style={{ display: 'flex', gap: '4px', flexWrap: 'wrap', marginBottom: '6px' }}>
        {PERSONA_PERIOD_OPTIONS.map((time) => (
          <button
            key={time}
            type="button"
            className={`btn btn-sm ${selectedTime === time ? 'btn-primary' : 'btn-outline-primary'}`}
            onClick={() => setSelectedTime(time)}
          >
            {time}期
          </button>
        ))}
      </div>
      <Plot
        data={[
          {
            type: "pie",
            values: chartData.map((item) => item.value),
            labels: chartData.map((item) => truncateLabel(item.label)),
            customdata: chartData.map((item) => item.label),
            direction: "clockwise",
            sort: false,
            textinfo: "percent",
            textposition: "inside",
            hovertemplate: "%{customdata}<br>%{percent}<extra></extra>",
            marker: {
              colors: chartData.map((item) => (item.label === 'その他' ? 'rgb(200, 200, 200)' : colormap[item.label])),
            },
          },
        ]}
        layout={{
          title: title,
          showlegend: true,
          plot_bgcolor: "white",
          paper_bgcolor: "white",
          margin: { t: 70, b: 90, l: 20, r: 20 },
          legend: {
            orientation: "h",
            x: 0,
            y: -0.02,
            xanchor: "left",
            yanchor: "top",
            entrywidthmode: "fraction",
            entrywidth: 0.5,
          },
        }}
        config={{ responsive: true, displayModeBar: false }}
        style={{ width: '100%', height: '100%', minHeight: 0 }} // 必ず全体サイズを親要素に合わせ
      />
    </div>
  );
};

export default PlotPieA;
